using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using ITDigitacao.Core;
namespace ITDigitacao.Legacy.App {
 internal static class Program { [STAThread] private static void Main(){ new Application().Run(new MainWindow()); } }
 internal sealed class MainWindow:Window {
  readonly string root=AppDomain.CurrentDomain.BaseDirectory; ActivityRepository repo; SessionManager session; StackPanel page; TextBox query,entry; ComboBox cat,diff; TextBlock stats,clock; DispatcherTimer timer;
  static readonly Brush Red=new SolidColorBrush(Color.FromRgb(217,0,0)), Ink=new SolidColorBrush(Color.FromRgb(23,23,23));
  public MainWindow(){Title="IT Digitação";Width=1000;Height=700;MinWidth=800;MinHeight=560;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=Brushes.White;
   try{using(FileStream s=File.OpenRead(Path.Combine(root,"atividades.json")))repo=ActivityRepository.Load(s);}catch(Exception e){MessageBox.Show("Falha ao carregar catálogo: "+e.Message);}
   DockPanel shell=new DockPanel(); Border banner=new Border{Background=Red,Padding=new Thickness(20)};DockPanel.SetDock(banner,Dock.Top);StackPanel bar=new StackPanel{Orientation=Orientation.Horizontal};bar.Children.Add(T("IT DIGITAÇÃO",23,true,Brushes.White));Nav(bar,"Início",Home);Nav(bar,"Biblioteca",Library);Nav(bar,"Guia ABNT2",Guide);Nav(bar,"Configurações",Settings);banner.Child=bar;shell.Children.Add(banner);
   ScrollViewer scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};page=new StackPanel{Margin=new Thickness(30)};scroll.Content=page;shell.Children.Add(scroll);Content=shell;Home();timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=delegate{if(session!=null){session.Tick();if(session.Finished)Results();if(clock!=null)clock.Text="Restante "+session.Remaining.ToString(@"mm\:ss");}};timer.Start(); }
  TextBlock T(string s,double n,bool bold,Brush brush=null){return new TextBlock{Text=s,FontSize=n,FontWeight=bold?FontWeights.Bold:FontWeights.Normal,Foreground=brush??Ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(6)};}
  Button B(string s,Action a,bool primary=true){Button b=new Button{Content=s,Padding=new Thickness(14,9,14,9),Margin=new Thickness(5),Background=primary?Red:Brushes.White,Foreground=primary?Brushes.White:Ink,BorderBrush=Red};b.Click+=delegate{a();};return b;}
  void Nav(Panel p,string s,Action a){p.Children.Add(B(s,a,false));} void Reset(string h,string sub){page.Children.Clear();page.Children.Add(T(h,29,true));page.Children.Add(T(sub,15,false));}
  void Home(){Reset("Vamos aprender algo incrível hoje?","Pratique digitação e descubra novos conhecimentos.");Image m=Pic("Assets/mascote-boas-vindas.png",190);page.Children.Add(m);page.Children.Add(B("Começar prática",delegate{if(session==null)session=new SessionManager(10,new SessionClock());Library();}));page.Children.Add(B("Explorar biblioteca",Library,false));}
  Image Pic(string f,double h){Image i=new Image{Height=h,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(5)};string p=Path.Combine(root,f);if(File.Exists(p))i.Source=new BitmapImage(new Uri(p));return i;}
  void Library(){Reset("Biblioteca educativa","Todas as categorias e atividades locais.");if(repo==null)return;query=new TextBox{Width=260,Padding=new Thickness(8),Margin=new Thickness(4)};cat=new ComboBox{Width=240,Margin=new Thickness(4),ItemsSource=new string[]{"Todas"}.Concat(repo.Categories.Select(x=>x.Name)).ToArray(),SelectedIndex=0};diff=new ComboBox{Width=170,Margin=new Thickness(4),ItemsSource=new string[]{"Todas","Iniciante","Intermediário","Avançado"},SelectedIndex=0};StackPanel f=new StackPanel{Orientation=Orientation.Horizontal};f.Children.Add(query);f.Children.Add(cat);f.Children.Add(diff);f.Children.Add(B("Filtrar",Render));page.Children.Add(f);Render();}
  void Render(){string c=cat.SelectedIndex>0?repo.Categories[cat.SelectedIndex-1].Id:null;string d=diff.SelectedIndex>0?(string)diff.SelectedItem:null;var acts=repo.Find(query.Text,d,c);for(int i=page.Children.Count-1;i>=2;i--)page.Children.RemoveAt(i);page.Children.Add(T(acts.Count+" atividades",14,false));foreach(Activity a in acts){Border card=new Border{BorderBrush=Red,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(9),Padding=new Thickness(12),Margin=new Thickness(5)};StackPanel row=new StackPanel();row.Children.Add(T(a.Title,18,true));row.Children.Add(T(a.CategoryName+" • "+a.Difficulty+" • "+a.EstimatedMinutes+" min",13,false));row.Children.Add(T(a.Description,14,false));row.Children.Add(B("Praticar",delegate{session=session??new SessionManager(10,new SessionClock());session.Open(a);Practice();}));card.Child=row;page.Children.Add(card);}}
  void Practice(){Activity a=session.Activity;Reset(a.Title,"Digite o texto, incluindo espaços e acentos.");page.Children.Add(T(a.Text,18,true));entry=new TextBox{AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=130,FontSize=18,Padding=new Thickness(10)};entry.TextChanged+=delegate{session.Apply(entry.Text);};page.Children.Add(entry);clock=T("Restante "+session.Remaining.ToString(@"mm\:ss"),19,true);page.Children.Add(clock);stats=T("Métricas atualizadas ao digitar",14,false);page.Children.Add(stats);entry.TextChanged+=delegate{if(session.Engine!=null)stats.Text="Progresso "+session.Engine.Progress.ToString("0")+"% • Erros "+session.TotalErrors+" • Precisão "+(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—")+" • "+(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#")+" ppm":"—");};page.Children.Add(B("Encerrar atividade",Results));page.Children.Add(B("Biblioteca",Library,false));}
  void Results(){Reset("Resumo da prática","Continue praticando para conquistar novas metas.");page.Children.Add(Pic("Assets/mascote-celebrando.png",150));if(session!=null){page.Children.Add(T("Atividades concluídas: "+session.CompletedCount,18,true));page.Children.Add(T("Precisão "+(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—")+" • Erros "+session.TotalErrors+" • Corrigidos "+session.CorrectedErrors+" • Velocidade "+(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#")+" ppm":"—"),15,false));page.Children.Add(T("Estrelas: "+SessionAwards.Stars(session.Evaluated,session.Accuracy),18,true));}clock=null;page.Children.Add(B("Voltar à biblioteca",Library));page.Children.Add(B("Início",Home,false));}
  void Guide(){Reset("Guia ABNT2","Posição inicial: ASDF JKLÇ. Polegares na barra de espaço.");page.Children.Add(Pic("Assets/mascote-ensinando.png",170));page.Children.Add(T("Mão esquerda: mindinho A, anelar S, médio D, indicador F. Mão direita: indicador J, médio K, anelar L, mindinho Ç.",17,false));page.Children.Add(B("Exercitar posição inicial",delegate{Activity a=Activity.HomeRowExercise();session=session??new SessionManager(10,new SessionClock());session.Open(a);Practice();}));}
  void Settings(){Reset("Configurações","Preferências desta instalação local.");page.Children.Add(T("Tamanho de fonte",16,true));Slider s=new Slider{Minimum=12,Maximum=28,Value=16,Width=300,HorizontalAlignment=HorizontalAlignment.Left};page.Children.Add(s);CheckBox sound=new CheckBox{Content="Sons",Margin=new Thickness(6)};page.Children.Add(sound);CheckBox metrics=new CheckBox{Content="Exibir métricas",IsChecked=true,Margin=new Thickness(6)};page.Children.Add(metrics);page.Children.Add(B("Salvar",delegate{MessageBox.Show("Configurações aplicadas durante esta sessão.");}));}
 }
}
